def find_length(s):
    max_diff = 0
    zero_count, one_count = 0, 0

    for char in s:
        if char == '0':
            zero_count += 1
        else:
            one_count += 1

        current_diff = abs(zero_count - one_count)

        if current_diff > max_diff:
            max_diff = current_diff

    return max_diff
```

