```python
def get_median(a, b):
    n = len(a)
    if n > n:
        return get_median(b, a)
    m = min(n, len(b))
    i, j = 0, 0
    while i < n or j < m:
        if i < n and (j >= m or a[i] <= b[j]):
            k = a[i]
            i += 1
        else:
            k = b[j]
            j += 1
        if (n + m) % 2 == 1:
            return k
        elif (n + m) // 2 == n:
            return a[n - 1]
        elif (n + m) // 2 == m:
            return b[m - 1]
```

