```python
def pancake_sort(arr):
    def flip(sub_arr, k):
        """Flip sub_arr[0:k+1] from largest to smallest."""
        for i in range(k // 2 + 1):
            sub_arr[i], sub_arr[k - i] = sub_arr[k - i], sub_arr[i]

    n = len(arr)
    for size in range(n, 1, -1):
        # Find the index of the maximum element in arr[:size]
        max_idx = arr[:size].index(max(arr[:size]))
        # Move the maximum element to the end if it's not already there
        if max_idx != size - 1:
            if max_idx < size - 1:
                flip(arr, max_idx + 1)  # Flip up to the current position
                flip(arr, size)         # Flip to place the max at its correct position
        else:  # If the max is already at the end, move one step back
            flip(arr, size - 1)
    return arr
```

