def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    s_list = list(s)
    i, j = 0, len(s) - 1

    while i < j:
        if s[i] not in vowels:
            i += 1
        elif s[j] not in vowels:
            j -= 1
        else:
            s_list[i], s_list[j] = s_list[j], s_list[i]
            i += 1
            j -= 1

    return ''.join(s_list)

# Test case
assert reverse_vowels("Python") == "Python"
```

