```python
def find_kth(arr1, arr2, k):
    i = j = 0
    while True:
        if i == len(arr1):
            return arr2[k - 1]
        if j == len(arr2):
            return arr1[k - 1]
        if k == 1:
            return min(arr1[i], arr2[j])

        next_i = min(i + k // 2, len(arr1)) - 1
        next_j = min(j + k // 2, len(arr2)) - 1

        if arr1[next_i] <= arr2[next_j]:
            k -= (next_i - i + 1)
            i = next_i + 1
        else:
            k -= (next_j - j + 1)
            j = next_j + 1
```

