def search(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[right]:
            # The target is in the left half
            right = mid
        else:
            # The target is in the right half or at mid
            left = mid + 1

    return nums[left]
```

