def find_solution(a, b, n):
    gcd_ab = extended_gcd(a, b)
    if gcd_ab * a + gcd_ab * b != n:
        return None
    x, y = gcd_ab // a, gcd_ab // b
    return (x % a, y % b)

def extended_gcd(x, y):
    if y == 0:
        return (x, 1, 0)
    else:
        g, x1, y1 = extended_gcd(y, x % y)
        t = x // y
        return (g, y1, x1 - t * y1)
```

