def sum_common_divisors(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def is_divisor(n, divisor):
        return n % divisor == 0

    common_divisors = [i for i in range(1, min(a, b) + 1) if is_divisor(a, i) and is_divisor(b, i)]
    return sum(common_divisors)
```

