```python
def sequence(n):
    if n <= 2:
        return n - 1
    else:
        def helper(k, memo={}):
            if k in memo:
                return memo[k]
            elif k % 2 == 0:
                memo[k] = helper(k // 2, memo) + helper(k // 3, memo)
            else:
                memo[k] = helper(k * 2, memo) + helper(k * 3, memo) + helper(k * 5, memo)
            return memo[k]

        return helper(n)
```

