def right_insertion(nums, val):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < val:
            left = mid + 1
        else:
            right = mid - 1
    return left

def max_subarray_product(nums):
    if not nums:
        return 0
    max_prod = min_prod = res = nums[0]
    for num in nums[1:]:
        temp_max = max(num, max_prod * num, min_prod * num)
        min_prod = min(num, max_prod * num, min_prod * num)
        max_prod = temp_max
        res = max(res, max_prod)
    return res

