def pancake_sort(arr):
    def flip(subarr, pos):
        start = 0
        while start < pos:
            subarr[start], subarr[pos] = subarr[pos], subarr[start]
            start += 1
            pos -= 1

    n = len(arr)
    for i in range(n, 1, -1):
        max_index = arr.index(max(arr[:i]))
        if max_index != i - 1:
            if max_index != 0:
                flip(arr, max_index)
            flip(arr, i - 1)
    return arr

def convert_list_dictionary(keys, values, ids):
