def max_product(nums):
    if not nums:
        return 0
    stack = []
    max_prod = 1
    for num in nums:
        while stack and stack[-1] < num:
            max_prod *= stack.pop()
        stack.append(num)
    while stack:
        max_prod *= stack.pop()
    return max_prod - 1

