def even_binomial_Coeff_Sum(n):
    return sum(binomial_coeff(n, 2*i) for i in range(n//2 + 1))

def binomial_coeff(n, k):
    if k > n - k:
        k = n - k
    c = [0] * (k + 1)
    c[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            c[j] += c[j-1]
    return c[k]

def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    s_list = list(s)
    left, right = 0, len(s) - 1

    while left < right:
        if s_list[left] not in vowels:
            left += 1
        elif s_list[right] not in vowels:
            right -= 1
        else:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return ''.join(s_list)

def find_Index(n):
    low, high = 10**(n-1), 10**n - 1
    while low < high:
        mid = (low + high) // 2
        if mid * (mid + 1) // 2 < 10**(n-1):
            low = mid + 1
        else:
            high = mid
    return low - 1

def diff_even_odd(nums):
    even = None
    odd = None
    for num in nums:
        if even is None and num % 2 == 0:
            even = num
        elif odd is None and num % 2 != 0:
            odd = num
        if even is not None and odd is not None:
            break
    return even - odd

