def check_expression(expr):
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}
    for char in expr:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs.keys():
            if stack == [] or pairs[char] != stack.pop():
                return False
    return stack == []

def newman_prime(n):
    if n == 1:
        return 2
    a, b = 4, 29
    for _ in range(n - 1):
        a, b = b, (b**2 + 3*b + 2) // 2
