def max_run_uppercase(s):
    max_run = current_run = 0
    for char in s:
        if char >= 'A' and char <= 'Z':
            current_run += 1
            max_run = max(max_run, current_run)
        else:
            current_run = 0
    return max_run

def is_perfect_square(n):
    if n < 0:
        return False
    root = int(n ** 0.5)
    return root * root == n

def search(arr):
