def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 0
    return 1 + max(dict_depth(v) for v in d.values())

def heap_sort(arr):
    def heapify(arr, n, i):
        largest = i
        l = 2 * i + 1
        r = 2 * i + 2

        if l < n and arr[i] < arr[l]:
            largest = l

        if r < n and arr[largest] < arr[r]:
            largest = r

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, n, largest)

    n = len(arr)

    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        heapify(arr, i, 0)

    return arr

def prime_num(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def toggle_middle_bits(n):
    if n < 2:
        return n
    mask = (1 << (n.bit_length() - 1)) - 3
    return (n & mask) | ((n & mask) >> 1) | ((n & mask) << 1)

def sum_Of_Subarray_Prod(arr):
    total_sum = 0
    n = len(arr)
    for i in range(n):
        product = 1
        for j in range(i, n):
            product *= arr[j]
            total_sum += product
    return total_sum

def cal_sum(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 3
    elif n == 2:
        return 4
    else:
        a, b, c = 3, 4, 4
        for i in range(3, n + 1):
            a, b, c = b, c, a + b
        return a + b + c + cal_sum(n - 1)

def get_ludic(n):
    if n < 8:
        return []
    ludics = [1, 2, 3, 5, 7]
    i = 4
    while True:
        next_ludic = ludics[-1] + i
        if next_ludic > n:
            break
        ludics.append(next_ludic)
        j = 1
        while (j * ludics[-1]) <= n:
            ludics.append(ludics[-1] - j)
            j += 1
        i += 1
    return ludics[:-1]

def bell_number(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    bell = [[0 for i in range(n+1)] for j in range(n+1)]
    bell[0][0] = 1
    for i in range(1, n+1):
        bell[i][0] = bell[i-1][i-1]
        for j in range(1,i+1):
            bell[i][j] = bell[i-1][j-1] + bell[i][j-1]
    return bell[n][0]

def divisible_by_digits(startnum, endnum):
    def is_divisible_by_its_digits(n):
        for digit in str(n):
            if int(digit) == 0 or n % int(digit) != 0:
                return False
        return True

    return [n for n in range(startnum, endnum + 1) if is_divisible_by_its_digits(n)]

def next_smallest_palindrome(n):
    n += 1
    while not is_palindrome(str(n)):
        n += 1
    return n

def is_palindrome(s):
