def get_pairs_count(nums, sum):
    count = 0
    num_counts = {}
    for num in nums:
        complement = sum - num
        if complement in num_counts:
            count += num_counts[complement]
        if num in num_counts:
            num_counts[num] += 1
        else:
            num_counts[num] = 1
    return count

def convert(complex_num):
    r = abs(complex_num)
    theta = cmath.phase(complex_num)
    return (r, theta)

def count_Primes_nums(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    count = 0
    for i in range(2, n):
        if is_prime(i):
            count += 1
    return count

def maxAverageOfPath(matrix):
    N = len(matrix)
    dp = [[[-float('inf')] * (N+1) for _ in range(N)] for _ in range(N)]

    def dfs(r, c, count):
        if r == N-1 and c == N-1:
            return matrix[r][c] / count

        if dp[r][c][count] != -float('inf'):
            return dp[r][c][count]

        right = dfs(r, c+1, count+1) if c < N-1 else -float('inf')
        down = dfs(r+1, c, count+1) if r < N-1 else -float('inf')

        dp[r][c][count] = max(right, down) + matrix[r][c] / count
        return dp[r][c][count]

    return dfs(0, 0, 1)

def max_occurrences(nums):
    freq = {}
