def amicable_numbers_sum(n):
    def is_amicable(a):
        b = sum(is_divisor(i) for i in range(1, a) if a % i == 0)
        return b > a and a == sum(is_divisor(j) for j in range(1, b) if b % j == 0)

    def is_divisor(num):
        return [i for i in range(1, num) if num % i == 0]

    total = 0
    for i in range(2, n + 1):
        if is_amicable(i):
            total += i

    return total

