def is_majority(arr, n, x):
    low, high = 0, n-1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            left = mid - 1
            while left >= 0 and arr[left] == x:
                left -= 1
            right = mid + 1
            while right < n and arr[right] == x:
                right += 1
            if right - left - 1 > n // 2:
                return True
            else:
                break
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return False

