def find_kth(arr1, arr2, k):
    if not arr1:
        return arr2[k]
    if not arr2:
        return arr1[k]
    if k == 0:
        return min(arr1[0], arr2[0])
    if k == len(arr1):
        return arr2[k - len(arr1)]
    if k == len(arr2):
        return arr1[k - len(arr2)]

    mid1 = len(arr1) // 2
    mid2 = len(arr2) // 2
    median1 = arr1[mid1]
    median2 = arr2[mid2]

    if median1 > median2:
        return find_kth(arr1[:mid1], arr2[mid2:], k - mid2)
    else:
        return find_kth(arr1[mid1:], arr2[:mid2], k - mid1)

