```python
def find_kth(arr1, arr2, k):
    i = j = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            if k == 1:
                return arr1[i]
            k -= 1
            i += 1
        else:
            if k == 1:
                return arr2[j]
            k -= 1
            j += 1
    if i < len(arr1):
        while i < len(arr1) and k > 0:
            if k == 1:
                return arr1[i]
            k -= 1
            i += 1
    elif j < len(arr2):
        while j < len(arr2) and k > 0:
            if k == 1:
                return arr2[j]
            k -= 1
            j += 1
    return None
```

