def max_sum_increasing_subseq(arr, n, k, m):
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if arr[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - arr[i - 1]] + arr[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][k]
```

