```python
def magic_square_test(matrix):
    n = len(matrix)
    if n != len(matrix[0]):
        return False

    # Calculate the sum of the first row
    target_sum = sum(matrix[0])

    # Check each row
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check each column
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target_sum:
            return False

    # Check both diagonals
    if sum(matrix[i][i] for i in range(n)) != target_sum or sum(matrix[i][n-i-1] for i in range(n)) != target_sum:
        return False

    return True
```

```python
def remove_lowercase(s):
    return ''.join(c for c in s if c.isupper())
```

```python
def amicable_numbers_sum(n):
    def is_amicable(a, b):
        return sum(divisors(a)) == b and sum(divisors(b)) == a

    divisors = lambda x: [i for i in range(1, x) if x % i == 0]
    amicable_pairs = [(a, b) for a in range(1, n+1) for b in range(a+1, n+1) if is_amicable(a, b)]
    return sum(x + y for x, y in amicable_pairs)
```

```python
def odd_length_sum(arr):
    total = 0
    n = len(arr)
    for i in range(n):
        for j in range(i+1, n+1):
            if (j-i) % 2 != 0:
                total += sum(arr[i:j])
    return total
```

